public int[] maxXor(int[] arr, int[] queries) {
    int[] result = new int[queries.length];
    for (int i = 0; i < queries.length; i++) {
        int best = 0;
        for (int a : arr) {
            best = Math.max(best, queries[i] ^ a);   // try every partner
        }
        result[i] = best;
    }
    return result;
}

static class Trie {
    Trie[] child = new Trie[2];
}

static final int B = 30;   // 10^9 fits in 30 bits

void insert(Trie root, int num) {
    Trie node = root;
    for (int i = B; i >= 0; i--) {
        int b = (num >> i) & 1;
        if (node.child[b] == null) node.child[b] = new Trie();
        node = node.child[b];
    }
}

int query(Trie root, int x) {
    Trie node = root;
    int res = 0;
    for (int i = B; i >= 0; i--) {
        int b = (x >> i) & 1;
        int want = 1 - b;                 // opposite bit maximizes XOR
        if (node.child[want] != null) {
            res |= (1 << i);
            node = node.child[want];
        } else {
            node = node.child[b];         // forced; this bit contributes 0
        }
    }
    return res;
}

public int[] maxXor(int[] arr, int[] queries) {
    Trie root = new Trie();
    for (int a : arr) insert(root, a);
    int[] result = new int[queries.length];
    for (int i = 0; i < queries.length; i++) result[i] = query(root, queries[i]);
    return result;
}

