class Trie:
    __slots__ = ("child",)
    def __init__(self) -> None:
        self.child: list = [None, None]

B = 30   # 10^9 fits in 30 bits

def insert(root: Trie, num: int) -> None:
    node = root
    for i in range(B, -1, -1):
        b = (num >> i) & 1
        if node.child[b] is None:
            node.child[b] = Trie()
        node = node.child[b]

def query(root: Trie, x: int) -> int:
    node, res = root, 0
    for i in range(B, -1, -1):
        b = (x >> i) & 1
        want = 1 - b                      # opposite bit maximizes XOR
        if node.child[want] is not None:
            res |= (1 << i)
            node = node.child[want]
        else:
            node = node.child[b]          # forced; this bit contributes 0
    return res

def maxXor(arr: list[int], queries: list[int]) -> list[int]:
    root = Trie()
    for a in arr:
        insert(root, a)
    return [query(root, x) for x in queries]
